@ContinuousAt.eventually_lt : ∀ {α : Type u_1} {β : Type u_2} [inst : TopologicalSpace α] [inst_1 : LinearOrder α]
  [OrderClosedTopology α] {f g : β → α} [inst_3 : TopologicalSpace β] {x₀ : β},
  ContinuousAt f x₀ → ContinuousAt g x₀ → f x₀ < g x₀ → ∀ᶠ (x : β) in 𝓝 x₀, f x < g x

@ContinuousAt.div : ∀ {α : Type u_1} {G₀ : Type u_2} [inst : GroupWithZero G₀] [inst_1 : TopologicalSpace G₀]
  [ContinuousInv₀ G₀] [ContinuousMul G₀] {f g : α → G₀} [inst_4 : TopologicalSpace α] {a : α},
  ContinuousAt f a → ContinuousAt g a → g a ≠ 0 → ContinuousAt (f / g) a
